create or replace function app_private.has_institution_permission(
  target_institution_id uuid,
  target_permission_code text,
  target_unit_id uuid default null,
  target_group_id uuid default null,
  require_institution_scope boolean default false
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  with current_person as (
    select app_private.current_person_id() as person_id
  ),
  active_memberships as (
    select membership.id
    from public.institution_memberships membership
    join current_person on current_person.person_id = membership.person_id
    where membership.institution_id = target_institution_id
      and membership.status = 'active'
      and membership.revoked_at is null
  ),
  applicable_role_permissions as (
    select role_permission.effect
    from active_memberships membership
    join public.institution_role_assignments assignment
      on assignment.membership_id = membership.id
     and assignment.status = 'active'
     and (assignment.starts_at is null or assignment.starts_at <= pg_catalog.now())
     and (assignment.expires_at is null or assignment.expires_at > pg_catalog.now())
    join public.institution_roles role_record
      on role_record.id = assignment.role_id
     and role_record.status = 'active'
     and (
       role_record.institution_id is null
       or role_record.institution_id = target_institution_id
     )
    join public.institution_role_permissions role_permission
      on role_permission.role_id = role_record.id
     and role_permission.status = 'active'
     and role_permission.revoked_at is null
    join public.institution_permissions permission_record
      on permission_record.id = role_permission.permission_id
     and permission_record.code = target_permission_code
     and permission_record.status = 'active'
    where (
      (
        require_institution_scope
        and assignment.scope_kind = 'institution'
      )
      or (
        not require_institution_scope
        and (
          assignment.scope_kind = 'institution'
          or (
            assignment.scope_kind = 'unit'
            and target_unit_id is not null
            and assignment.scope_unit_id = target_unit_id
          )
          or (
            assignment.scope_kind = 'group'
            and target_group_id is not null
            and assignment.scope_group_id = target_group_id
            and (
              target_unit_id is null
              or assignment.scope_unit_id = target_unit_id
            )
          )
        )
      )
    )
  ),
  applicable_direct_grants as (
    select 1
    from active_memberships membership
    join public.institution_role_grants direct_grant
      on direct_grant.membership_id = membership.id
     and direct_grant.permission_code = target_permission_code
     and direct_grant.status = 'active'
     and (direct_grant.starts_at is null or direct_grant.starts_at <= pg_catalog.now())
     and (direct_grant.expires_at is null or direct_grant.expires_at > pg_catalog.now())
    where (
      (
        require_institution_scope
        and direct_grant.scope_kind = 'institution'
      )
      or (
        not require_institution_scope
        and (
          direct_grant.scope_kind = 'institution'
          or (
            direct_grant.scope_kind = 'unit'
            and target_unit_id is not null
            and direct_grant.scope_id = target_unit_id
          )
          or (
            direct_grant.scope_kind = 'group'
            and target_group_id is not null
            and direct_grant.scope_id = target_group_id
          )
        )
      )
    )
  )
  select
    not exists (
      select 1
      from applicable_role_permissions
      where effect = 'deny'
    )
    and (
      exists (
        select 1
        from applicable_role_permissions
        where effect = 'allow'
      )
      or exists (select 1 from applicable_direct_grants)
    )
$$;

create or replace function app_private.has_activity_context_access(
  target_activity_id uuid,
  target_unit_id uuid default null,
  target_group_id uuid default null
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.activity_group_assignments assignment
    join public.activity_group_links group_link
      on group_link.id = assignment.activity_group_link_id
     and group_link.institution_id = assignment.institution_id
    join public.activity_definitions activity
      on activity.id = group_link.activity_id
     and activity.institution_id = group_link.institution_id
    where assignment.person_id = app_private.current_person_id()
      and assignment.status = 'active'
      and assignment.revoked_at is null
      and group_link.status = 'active'
      and activity.status = 'active'
      and activity.id = target_activity_id
      and (target_unit_id is null or group_link.unit_id = target_unit_id)
      and (target_group_id is null or group_link.group_id = target_group_id)
  )
$$;

create or replace function app_private.has_activity_capability(
  target_activity_id uuid,
  target_group_id uuid,
  target_capability_code text
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  with current_assignment as (
    select
      assignment.id,
      group_link.permission_profile_id
    from public.activity_group_assignments assignment
    join public.activity_group_links group_link
      on group_link.id = assignment.activity_group_link_id
     and group_link.institution_id = assignment.institution_id
    join public.activity_definitions activity
      on activity.id = group_link.activity_id
     and activity.institution_id = group_link.institution_id
    where assignment.person_id = app_private.current_person_id()
      and assignment.status = 'active'
      and assignment.revoked_at is null
      and group_link.status = 'active'
      and activity.status = 'active'
      and activity.id = target_activity_id
      and group_link.group_id = target_group_id
    limit 1
  ),
  target_capability as (
    select capability.id
    from public.activity_capabilities capability
    where capability.code = target_capability_code
      and capability.status = 'active'
  ),
  assignment_override as (
    select override_record.effect
    from current_assignment assignment
    join public.activity_assignment_permission_overrides override_record
      on override_record.assignment_id = assignment.id
    join target_capability capability
      on capability.id = override_record.capability_id
    limit 1
  ),
  profile_permission as (
    select profile_capability.effect
    from current_assignment assignment
    join public.activity_permission_profile_capabilities profile_capability
      on profile_capability.profile_id = assignment.permission_profile_id
    join target_capability capability
      on capability.id = profile_capability.capability_id
    limit 1
  )
  select case
    when not exists (select 1 from current_assignment) then false
    when exists (
      select 1 from assignment_override where effect = 'deny'
    ) then false
    when exists (
      select 1 from assignment_override where effect = 'allow'
    ) then true
    when exists (
      select 1 from profile_permission where effect = 'allow'
    ) then true
    else false
  end
$$;

create or replace function app_private.set_activity_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at := pg_catalog.now();
  return new;
end
$$;

create or replace function app_private.validate_activity_group_profile()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  profile_scope public.activity_permission_scope;
  profile_unit_id uuid;
begin
  if new.permission_profile_id is null then
    return new;
  end if;

  select profile.scope_kind, profile.unit_id
  into profile_scope, profile_unit_id
  from public.activity_permission_profiles profile
  where profile.id = new.permission_profile_id
    and profile.institution_id = new.institution_id;

  if profile_scope = 'unit' and profile_unit_id <> new.unit_id then
    raise check_violation using
      message = 'unit-scoped activity profile must match the activity group unit';
  end if;

  return new;
end
$$;

create or replace function app_private.enforce_activity_active_unit()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  target_activity_id uuid;
  row_data jsonb;
begin
  row_data := case
    when tg_op = 'DELETE' then to_jsonb(old)
    else to_jsonb(new)
  end;
  target_activity_id := coalesce(
    (row_data ->> 'activity_id')::uuid,
    (row_data ->> 'id')::uuid
  );

  if not exists (
    select 1
    from public.activity_definitions activity
    where activity.id = target_activity_id
  ) then
    return coalesce(new, old);
  end if;

  if not exists (
    select 1
    from public.activity_unit_links unit_link
    where unit_link.activity_id = target_activity_id
      and unit_link.status = 'active'
      and (unit_link.ends_at is null or unit_link.ends_at > pg_catalog.now())
  ) then
    raise check_violation using
      message = 'activity must retain at least one active unit link';
  end if;

  return coalesce(new, old);
end
$$;

create or replace function app_private.audit_activity_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  row_data jsonb;
  before_data jsonb;
  after_data jsonb;
  target_institution_id uuid;
  target_object_id uuid;
  actor_person_id uuid;
  actor_membership_id uuid;
begin
  before_data := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end;
  after_data := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end;
  row_data := coalesce(after_data, before_data);
  target_object_id := (row_data ->> 'id')::uuid;

  if row_data ? 'institution_id' then
    target_institution_id := (row_data ->> 'institution_id')::uuid;
  elsif tg_table_name = 'activity_permission_profile_capabilities' then
    select profile.institution_id
    into target_institution_id
    from public.activity_permission_profiles profile
    where profile.id = (row_data ->> 'profile_id')::uuid;
  elsif tg_table_name = 'activity_assignment_permission_overrides' then
    select assignment.institution_id
    into target_institution_id
    from public.activity_group_assignments assignment
    where assignment.id = (row_data ->> 'assignment_id')::uuid;
  end if;

  actor_person_id := app_private.current_person_id();

  select membership.id
  into actor_membership_id
  from public.institution_memberships membership
  where membership.person_id = actor_person_id
    and membership.institution_id = target_institution_id
    and membership.status = 'active'
    and membership.revoked_at is null
  limit 1;

  insert into audit.audit_logs(
    actor_person_id,
    actor_membership_id,
    mfa_aal,
    action_code,
    object_type,
    object_id,
    institution_id,
    outcome,
    reason,
    before_json,
    after_json
  ) values (
    actor_person_id,
    actor_membership_id,
    auth.jwt() ->> 'aal',
    'activity_' || lower(tg_op),
    tg_table_name,
    target_object_id,
    target_institution_id,
    'success',
    nullif(current_setting('coelo.audit_reason', true), ''),
    before_data,
    after_data
  );

  return coalesce(new, old);
end
$$;

create or replace function app_private.create_activity_for_institution(
  target_institution_id uuid,
  initial_unit_id uuid,
  activity_name text,
  activity_description text default null,
  audit_reason text default null
)
returns public.activity_definitions
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor_person_id uuid;
  created_activity public.activity_definitions;
begin
  actor_person_id := app_private.current_person_id();

  if auth.uid() is null or actor_person_id is null then
    raise insufficient_privilege using message = 'authenticated person is required';
  end if;

  if btrim(coalesce(activity_name, '')) = '' then
    raise check_violation using message = 'activity name is required';
  end if;

  if not exists (
    select 1
    from public.units unit_record
    where unit_record.id = initial_unit_id
      and unit_record.institution_id = target_institution_id
      and unit_record.status = 'active'
  ) then
    raise foreign_key_violation using
      message = 'initial unit must be active and belong to the institution';
  end if;

  if not app_private.has_institution_permission(
    target_institution_id,
    'activities.create',
    initial_unit_id,
    null,
    true
  ) then
    raise insufficient_privilege using
      message = 'activities.create at institution scope is required';
  end if;

  perform set_config('coelo.audit_reason', coalesce(audit_reason, ''), true);

  insert into public.activity_definitions(
    institution_id,
    name,
    description,
    origin_scope_kind,
    created_by_person_id
  ) values (
    target_institution_id,
    btrim(activity_name),
    nullif(btrim(coalesce(activity_description, '')), ''),
    'institution',
    actor_person_id
  )
  returning * into created_activity;

  insert into public.activity_unit_links(
    activity_id,
    institution_id,
    unit_id,
    linked_by_person_id
  ) values (
    created_activity.id,
    target_institution_id,
    initial_unit_id,
    actor_person_id
  );

  return created_activity;
end
$$;

create or replace function app_private.create_activity_for_unit(
  origin_unit_id uuid,
  activity_name text,
  activity_description text default null,
  audit_reason text default null
)
returns public.activity_definitions
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor_person_id uuid;
  derived_institution_id uuid;
  created_activity public.activity_definitions;
begin
  actor_person_id := app_private.current_person_id();

  if auth.uid() is null or actor_person_id is null then
    raise insufficient_privilege using message = 'authenticated person is required';
  end if;

  if btrim(coalesce(activity_name, '')) = '' then
    raise check_violation using message = 'activity name is required';
  end if;

  select unit_record.institution_id
  into derived_institution_id
  from public.units unit_record
  where unit_record.id = origin_unit_id
    and unit_record.status = 'active';

  if derived_institution_id is null then
    raise foreign_key_violation using message = 'active origin unit is required';
  end if;

  if not app_private.has_institution_permission(
    derived_institution_id,
    'activities.create',
    origin_unit_id,
    null,
    false
  ) then
    raise insufficient_privilege using
      message = 'activities.create for the origin unit is required';
  end if;

  perform set_config('coelo.audit_reason', coalesce(audit_reason, ''), true);

  insert into public.activity_definitions(
    institution_id,
    name,
    description,
    origin_scope_kind,
    origin_unit_id,
    created_by_person_id
  ) values (
    derived_institution_id,
    btrim(activity_name),
    nullif(btrim(coalesce(activity_description, '')), ''),
    'unit',
    origin_unit_id,
    actor_person_id
  )
  returning * into created_activity;

  insert into public.activity_unit_links(
    activity_id,
    institution_id,
    unit_id,
    linked_by_person_id
  ) values (
    created_activity.id,
    derived_institution_id,
    origin_unit_id,
    actor_person_id
  );

  return created_activity;
end
$$;

create or replace function public.create_activity_for_institution(
