do $$
declare
  current_table text;
begin
  foreach current_table in array array[
    'activity_capabilities',
    'activity_definitions',
    'activity_unit_links',
    'activity_permission_profiles',
    'activity_permission_profile_capabilities',
    'activity_group_links',
    'activity_group_assignments',
    'activity_assignment_permission_overrides',
    'activity_suggestions'
  ]
  loop
    execute format('alter table public.%I enable row level security', current_table);
    execute format(
      'revoke all on table public.%I from public, anon, authenticated',
      current_table
    );
    execute format(
      'grant all on table public.%I to service_role',
      current_table
    );
  end loop;
end
$$;

