      and app_private.has_institution_permission(
        assignment.institution_id,
        'activities.manage_permissions',
        group_link.unit_id,
        group_link.group_id,
        false
      )
  )
);

create policy activity_assignment_overrides_authorized_update
on public.activity_assignment_permission_overrides
for update
to authenticated
using (
  exists (
    select 1
    from public.activity_group_assignments assignment
    join public.activity_group_links group_link
      on group_link.id = assignment.activity_group_link_id
    where assignment.id = activity_assignment_permission_overrides.assignment_id
      and app_private.has_institution_permission(
        assignment.institution_id,
        'activities.manage_permissions',
        group_link.unit_id,
        group_link.group_id,
        false
      )
  )
)
with check (
  exists (
    select 1
    from public.activity_group_assignments assignment
    join public.activity_group_links group_link
      on group_link.id = assignment.activity_group_link_id
    where assignment.id = activity_assignment_permission_overrides.assignment_id
      and app_private.has_institution_permission(
        assignment.institution_id,
        'activities.manage_permissions',
        group_link.unit_id,
        group_link.group_id,
        false
      )
  )
);

create policy activity_assignment_overrides_authorized_delete
on public.activity_assignment_permission_overrides
for delete
to authenticated
using (
  exists (
    select 1
    from public.activity_group_assignments assignment
    join public.activity_group_links group_link
      on group_link.id = assignment.activity_group_link_id
    where assignment.id = activity_assignment_permission_overrides.assignment_id
