create policy activity_suggestions_context_read
on public.activity_suggestions
for select
to authenticated
using (
  (select app_private.has_platform_permission('platform.read'))
  or app_private.has_institution_permission(
    institution_id,
    'activities.read',
    unit_id,
    null,
    scope_kind = 'institution'
  )
);

create policy activity_suggestions_authorized_insert
on public.activity_suggestions
for insert
to authenticated
with check (
  app_private.has_institution_permission(
    institution_id,
    'activities.create',
    unit_id,
    null,
    scope_kind = 'institution'
  )
);

create policy activity_suggestions_authorized_update
on public.activity_suggestions
for update
to authenticated
using (
  app_private.has_institution_permission(
    institution_id,
    'activities.create',
    unit_id,
    null,
    scope_kind = 'institution'
  )
)
with check (
  app_private.has_institution_permission(
    institution_id,
    'activities.create',
    unit_id,
    null,
    scope_kind = 'institution'
  )
);

with table_catalog(table_name, table_label, table_description) as (
  values
    ('activity_definitions', 'Atividades', 'Definicoes reutilizaveis de atividade pertencentes a uma instituicao.'),
    ('activity_unit_links', 'Atividades por unidade', 'Disponibilidade e vinculo obrigatorio de atividades com unidades.'),
    ('activity_group_links', 'Atividades por turma', 'Atividade aplicada no contexto de um grupo ou turma.'),
    ('activity_group_assignments', 'Pessoas por atividade e turma', 'Pessoas atribuidas a uma atividade dentro de uma turma.'),
    ('activity_capabilities', 'Capacidades de atividade', 'Catalogo de capacidades operacionais contextualizadas pela atividade.'),
    ('activity_permission_profiles', 'Perfis de permissao de atividade', 'Perfis reutilizaveis de capacidades por instituicao ou unidade.'),
    ('activity_permission_profile_capabilities', 'Capacidades por perfil de atividade', 'Capacidades liberadas ou negadas por perfil de atividade.'),
    ('activity_assignment_permission_overrides', 'Overrides por atribuicao de atividade', 'Excecoes de capacidade por pessoa, atividade e turma.'),
    ('activity_suggestions', 'Sugestoes de atividades', 'Sugestoes editaveis pertencentes a instituicao ou unidade.')
)
insert into public.schema_tables(
  schema_name,
  table_name,
  table_label,
  table_description,
  domain,
  status,
  version,
  updated_at
)
select
  'public',
  table_catalog.table_name,
  table_catalog.table_label,
  table_catalog.table_description,
  'activities',
  'active',
  1,
  now()
from table_catalog
on conflict (schema_name, table_name, version) do update set
  table_label = excluded.table_label,
  table_description = excluded.table_description,
  domain = excluded.domain,
  status = 'active',
  updated_at = now();

insert into public.schema_columns(
  schema_table_id,
  column_name,
  column_label,
  column_description,
  column_type,
  is_required,
  is_nullable,
  is_unique,
  is_filterable,
  is_importable,
  is_active,
  position,
  allowed_locales_json,
  aliases_json,
  examples_json,
  updated_at
)
select
  schema_table.id,
  column_info.column_name,
  case column_info.column_name
    when 'id' then 'ID'
    when 'activity_id' then 'Atividade'
    when 'activity_group_link_id' then 'Atividade na turma'
    when 'assignment_id' then 'Atribuicao'
    when 'capability_id' then 'Capacidade'
    when 'profile_id' then 'Perfil de permissao'
    when 'permission_profile_id' then 'Perfil de permissao'
    when 'institution_id' then 'Instituicao'
    when 'unit_id' then 'Unidade'
    when 'group_id' then 'Grupo'
    when 'person_id' then 'Pessoa'
    when 'membership_id' then 'Vinculo institucional'
    when 'name' then 'Nome'
    when 'code' then 'Codigo'
    when 'description' then 'Descricao'
    when 'status' then 'Status'
    when 'created_at' then 'Criado em'
    when 'updated_at' then 'Atualizado em'
    else initcap(replace(column_info.column_name, '_', ' '))
  end,
  'Campo ' || column_info.column_name || ' da tabela ' || schema_table.table_label || '.',
  case
    when column_info.data_type = 'USER-DEFINED'
      then column_info.udt_schema || '.' || column_info.udt_name
    else column_info.data_type
  end,
  column_info.is_nullable = 'NO' and column_info.column_default is null,
  column_info.is_nullable = 'YES',
  false,
  (
    column_info.column_name = 'id'
    or column_info.column_name like '%\_id' escape '\'
    or column_info.column_name in (
      'code',
      'template_code',
      'status',
      'scope_kind',
      'origin_scope_kind',
      'assignment_role'
    )
    or column_info.column_name like '%\_at' escape '\'
  ),
  column_info.table_name in (
    'activity_definitions',
    'activity_unit_links',
    'activity_group_links',
    'activity_group_assignments',
    'activity_suggestions'
  ),
  true,
  column_info.ordinal_position,
  '["pt-BR"]'::jsonb,
  '{}'::jsonb,
  '[]'::jsonb,
  now()
from information_schema.columns column_info
join public.schema_tables schema_table
  on schema_table.schema_name = column_info.table_schema
 and schema_table.table_name = column_info.table_name
 and schema_table.version = 1
where column_info.table_schema = 'public'
  and column_info.table_name in (
    'activity_definitions',
    'activity_unit_links',
    'activity_group_links',
    'activity_group_assignments',
    'activity_capabilities',
    'activity_permission_profiles',
    'activity_permission_profile_capabilities',
    'activity_assignment_permission_overrides',
    'activity_suggestions'
  )
on conflict (schema_table_id, column_name) do update set
  column_label = excluded.column_label,
  column_description = excluded.column_description,
  column_type = excluded.column_type,
  is_required = excluded.is_required,
  is_nullable = excluded.is_nullable,
  is_filterable = excluded.is_filterable,
  is_importable = excluded.is_importable,
  is_active = true,
  position = excluded.position,
  updated_at = now();
